package org.apache.commons.compress.compressors.bzip2;

import java.io.*;
import java.io.ByteArrayInputStream;
import java.io.IOException;
import java.io.InputStream;
import java.math.*;
import java.util.*;
import org.apache.commons.compress.compressors.CompressorInputStream;
import org.apache.commons.compress.compressors.bzip2.BZip2CompressorInputStream;
import org.junit.*;
import org.junit.Assert;
import org.junit.Test;
import static org.junit.Assert.*;

public class BZip2CompressorInputStream_BZip2CompressorInputStream_TriageGen0Test {











    /**
     * Test the static matches method.
     */
    @Test
    public void testMatches() {
        byte[] signature = new byte[]{(byte) 'B', (byte) 'Z', (byte) 'h'};
        byte[] data = new byte[]{(byte) 'B', (byte) 'Z', (byte) 'h', 0x01, 0x02};

        Assert.assertTrue(BZip2CompressorInputStream.matches(data, 3));
        Assert.assertFalse(BZip2CompressorInputStream.matches(data, 2));
        Assert.assertFalse(BZip2CompressorInputStream.matches(new byte[]{0x01, 0x02}, 2));
    }


}

